function nursingObserve(i){let x=nursingEntries()[i];if(!x)return;form('Fictional nursing observations',[['bp','Blood pressure','text'],['pulse','Pulse','text'],['temp','Temperature','text'],['resp','Respiratory rate','text'],['spo2','Oxygen saturation','text'],['condition','Patient condition','textarea'],['care','Care given','textarea'],['response','Patient response','textarea']],v=>{(db.extra['/nursing|0']??=[]).push({...v,patient:x.patient,encounter:x.id,date:new Date().toLocaleString(),status:'Recorded'});save('Recorded encounter-linked demo nursing observations')})}
function nursingView(){if(tab!==0)return '<h1>Nursing station</h1>'+extended();let rows=nursingEntries();return '<h1>Nursing station</h1><p>Active OPD and inpatient encounters · Fictional records</p><div class="tabs">'+['Patient Board','Medications','Filing'].map((t,i)=>'<button class="'+(i===tab?'primary':'')+'" onclick="changeTab('+i+')">'+t+'</button>').join('')+'</div><div class="card">'+table(['Patient','Encounter type','Location','Action'],rows.map((x,i)=>[esc(patient(x.patient)),esc(x.kind),esc(x.label),btn('Record observations','nursingObserve('+i+')')]))+'<h2 style="margin-top:22px">Observation history</h2>'+table(['Patient','Encounter','Date','BP','Pulse','Temp','Resp','SpO₂','Condition','Care','Response'],records('/nursing',0).map(x=>[esc(patient(x.patient)),esc(x.encounter),esc(x.date),esc(x.bp),esc(x.pulse),esc(x.temp),esc(x.resp),esc(x.spo2),esc(x.condition||x.note),esc(x.care),esc(x.response)]))+'</div>'}


const imagingRows=()=>db.extra['/imaging|0']??=[];
function imagingStatus(x){return ({Requested:'Pending',Reported:'Completed'})[x.status]||x.status}
function imagingAdvance(i){let x=imagingRows()[i],st=imagingStatus(x);if(st==='Pending'){x.status='In progress';x.startedAt=new Date().toLocaleString();save('Started fictional imaging request')}else if(st==='In progress'){form('Imaging findings',[['findings','Findings','textarea'],['impression','Impression','textarea'],['sonographer','Demo reporting clinician','text']],v=>{if(!v.findings.trim())return alert('Findings are required');Object.assign(x,v,{status:'Completed',reportedAt:new Date().toLocaleString()});save('Completed fictional imaging report')})}}
function imagingCorrect(i){let x=imagingRows()[i];if(imagingStatus(x)!=='Completed')return;form('Correct completed imaging report',[['findings','Corrected findings','textarea'],['impression','Corrected impression','textarea'],['reason','Reason for correction','text']],v=>{if(!v.findings.trim()||!v.reason.trim())return alert('Findings and reason required');(x.revisions??=[]).push({findings:x.findings,impression:x.impression,reason:v.reason,date:new Date().toLocaleString()});x.findings=v.findings;x.impression=v.impression;x.correctedAt=new Date().toLocaleString();save('Imaging findings corrected')})}
function imagingNew(){form('New fictional imaging request',[['patient','Patient','select',db.patients.map(p=>[p.id,p.name])],['study','Study / body region','text'],['modality','Modality','text'],['notes','Clinical indication','textarea']],v=>{imagingRows().push({...v,id:financialId(),item:v.study,status:'Pending',date:new Date().toLocaleString()});save('Created fictional imaging request')})}
function imagingCancel(i){let x=imagingRows()[i];if(imagingStatus(x)!=='Pending'||x.billed)return alert('Only unbilled pending requests can be cancelled.');if(confirm('Cancel this fictional request?')){x.status='Cancelled';save('Cancelled demo imaging request')}}
function imagingPrint(i){let x=imagingRows()[i];if(imagingStatus(x)!=='Completed')return;let w=window.open('','_blank');if(!w)return alert('Allow pop-ups to print.');w.document.write('<!doctype html><html><head><title>Demo imaging report</title></head><body style="font:14px Arial;margin:35px"><h1>MediTrack Pro — Imaging report</h1><strong>FICTIONAL DEMO — NOT FOR CLINICAL USE</strong><p>Patient: '+esc(patient(x.patient))+' · '+esc(x.patient)+'</p>'+[['visit','Visit'],['study','Study'],['modality','Modality'],['notes','Clinical indication'],['findings','Findings'],['impression','Impression'],['sonographer','Reporting clinician'],['reportedAt','Report date'],['correctedAt','Last correction']].map(([k,l])=>'<h3>'+l+'</h3><p style="white-space:pre-wrap">'+esc(x[k]||'—')+'</p>').join('')+'<p>Demo signature: __________________</p></body></html>');w.document.close();w.print()}
let imagingFilter='All';
function imagingSelect(v){imagingFilter=v;render()}
function imagingView(){if(tab===1)return '<h1>Medical imaging</h1>'+extended();let states=['All','Pending','In progress','Completed','Cancelled'];return '<h1>Medical imaging</h1><p>Imaging worklist and findings · Fictional records</p><div class="tabs">'+btn('Worklist','changeTab(0)')+btn('Uploads','changeTab(1)')+'</div><div class="grid">'+states.slice(1).map(t=>'<div class="card">'+t+'<div class="stat">'+imagingRows().filter(x=>imagingStatus(x)===t).length+'</div></div>').join('')+'</div><div class="card"><div class="row">'+btn('New request','imagingNew()')+'<select onchange="imagingSelect(this.value)">'+states.map(t=>'<option '+(t===imagingFilter?'selected':'')+'>'+t+'</option>').join('')+'</select><input placeholder="Search worklist" oninput="filterRows(this.value)"></div>'+table(['Patient','Visit','Study','Modality','Status','Findings','Impression','Actions'],imagingRows().map((x,i)=>({x,i})).filter(({x})=>imagingFilter==='All'||imagingStatus(x)===imagingFilter).map(({x,i})=>{let st=imagingStatus(x);return [esc(patient(x.patient)),esc(x.visit),esc(x.study||x.item),esc(x.modality),esc(st),esc(x.findings),esc(x.impression),st==='Pending'?btn('Start','imagingAdvance('+i+')')+' '+btn('Cancel','imagingCancel('+i+')'):st==='In progress'?btn('Enter findings','imagingAdvance('+i+')'):st==='Completed'?btn('Print','imagingPrint('+i+')')+' '+btn('Correct','imagingCorrect('+i+')'):'—']}))+'</div>'}


const claims=()=>db.extra['/insurance|2']??=[];
const policies=()=>db.extra['/insurance|1']??=[];
const claimStates=['Draft','Pending review','Ready for submission','Submitted','Under review','Approved','Partially approved','Rejected','Paid','Cancelled'];
function claimBuild(){let eligible=db.bills.filter(b=>balance(b)>0&&!b.claimId&&policies().some(p=>p.patient===b.patient&&p.status==='Active'));if(!eligible.length)return alert('Register an active demo insurance policy and create an outstanding invoice first.');form('Build fictional insurance claim',[['invoice','Outstanding invoice','select',eligible.map((b,i)=>[String(i),patient(b.patient)+' · '+b.item+' · SSP '+money(balance(b))])]],v=>{let b=eligible[+v.invoice],p=b&&policies().find(p=>p.patient===b.patient&&p.status==='Active');if(!b||!p||b.claimId||!balance(b))return alert('Invoice is no longer eligible.');let c={id:financialId(),invoice:b.id,patient:b.patient,provider:p.provider,member:p.member,amount:balance(b),status:'Draft',history:[],createdAt:new Date().toLocaleString()};b.claimId=c.id;claims().push(c);save('Built fictional insurance claim')})}
function claimStep(i){let c=claims()[i],next=({'Draft':['Pending review','Cancelled'],'Pending review':['Ready for submission','Cancelled'],'Ready for submission':['Submitted','Cancelled'],'Submitted':['Under review'],'Under review':['Approved','Partially approved','Rejected'],'Approved':['Paid'],'Partially approved':['Paid']})[c.status];if(!next)return;form('Update fictional claim',[['status','Next status','select',next.map(t=>[t,t])]],v=>{if(!next.includes(v.status))return;let apply=(details={})=>{let b=db.bills.find(b=>b.id===c.invoice);(c.history??=[]).push({from:c.status,to:v.status,date:new Date().toLocaleString()});Object.assign(c,details,{status:v.status});if(v.status==='Cancelled'&&b?.claimId===c.id)delete b.claimId;save('Updated fictional insurance claim to '+v.status)};if(v.status==='Partially approved'){setTimeout(()=>form('Partial approval',[['approved','Approved SSP','number']],d=>{let n=+d.approved;if(!Number.isSafeInteger(n)||n<=0||n>=Number(c.amount))return alert('Enter an amount below the claim total.');apply({approved:n})}),0)}else if(v.status==='Paid'){setTimeout(()=>form('Record simulated insurer payment',[['reference','Demo remittance reference','text']],d=>{let b=db.bills.find(b=>b.id===c.invoice),n=Number(c.approved??c.amount);if(!b||!Number.isSafeInteger(n)||n<=0||n>balance(b))return alert('Payment does not match the outstanding invoice.');b.paid=amountPaid(b)+n;b.status=b.paid>=Number(b.amount)?'Paid':'Partially paid';db.payments.push({id:financialId(),invoice:b.id,patient:b.patient,amount:n,method:'Insurance',reference:d.reference,date:new Date().toLocaleString()});apply({paid:n})}),0)}else apply(v.status==='Approved'?{approved:Number(c.amount)}:{})})}
function claimPrint(i){let c=claims()[i],b=db.bills.find(b=>b.id===c.invoice),w=window.open('','_blank');if(!w)return alert('Allow pop-ups to print.');w.document.write('<html><head><title>Demo claim</title></head><body style="font:14px Arial;margin:35px"><h1>MediTrack Pro — Insurance claim</h1><strong>FICTIONAL DEMO — NOT FOR SUBMISSION</strong>'+[['Claim',c.id],['Patient',patient(c.patient)],['Provider',c.provider],['Member',c.member],['Invoice',c.invoice],['Service',b?.item],['Claimed SSP',money(c.amount)],['Approved SSP',money(c.approved)],['Paid SSP',money(c.paid)],['Status',c.status]].map(([l,v])=>'<p><b>'+l+':</b> '+esc(v)+'</p>').join('')+'</body></html>');w.document.close();w.print()}
function insuranceView(){if(tab!==0&&tab!==2&&tab!==6)return '<h1>Insurance</h1>'+extended();let specs=modules['/insurance'];let tabs='<div class="tabs">'+specs.map((t,i)=>'<button class="'+(i===tab?'primary':'')+'" onclick="changeTab('+i+')">'+esc(t[0])+'</button>').join('')+'</div>';let summary='<div class="grid">'+[['Active policies',policies().filter(p=>p.status==='Active').length],['Claims',claims().length],['Claimed SSP',money(claims().reduce((a,c)=>a+Number(c.amount||0),0))],['Paid SSP',money(claims().reduce((a,c)=>a+Number(c.paid||0),0))]].map(([l,v])=>'<div class="card">'+l+'<div class="stat">'+v+'</div></div>').join('')+'</div>';let body=tab===2?btn('Build claim from invoice','claimBuild()')+table(['Claim','Patient','Provider','Invoice','Claimed SSP','Approved SSP','Paid SSP','Status','Actions'],claims().map((c,i)=>[esc(c.id),esc(patient(c.patient)),esc(c.provider),esc(c.invoice),money(c.amount),money(c.approved),money(c.paid),esc(c.status),(['Paid','Cancelled','Rejected'].includes(c.status)?'':btn('Advance','claimStep('+i+')')+' ')+btn('Print','claimPrint('+i+')')])):table(['Status','Count','Claimed SSP'],claimStates.map(t=>[t,claims().filter(c=>c.status===t).length,money(claims().filter(c=>c.status===t).reduce((a,c)=>a+Number(c.amount||0),0))]));return '<h1>Insurance</h1><p>Fictional policies and invoice-linked claims</p>'+summary+tabs+'<div class="card">'+body+'</div>'}


const ledgerAccounts=()=>db.extra['/general-ledger|0']??=[];
const ledgerEntries=()=>db.extra['/general-ledger|1']??=[];
const ledgerPeriods=()=>db.extra['/general-ledger|4']??=[];
function ledgerSeed(){let list=[['1000','Cash','Asset'],['1010','Bank Account','Asset'],['1020','Mobile Money','Asset'],['1100','Accounts Receivable','Asset'],['1200','Inventory - Pharmacy','Asset'],['2000','Accounts Payable','Liability'],['3000','Owner Equity','Equity'],['4000','Consultation Revenue','Revenue'],['4010','Laboratory Revenue','Revenue'],['4020','Pharmacy Revenue','Revenue'],['4030','Radiology Revenue','Revenue'],['4080','Other Revenue','Revenue'],['5000','Salaries & Wages','Expense'],['5010','Medical Supplies','Expense'],['5030','Utilities','Expense']];for(let [code,name,type] of list)if(!ledgerAccounts().some(a=>a.code===code))ledgerAccounts().push({code,name,type,status:'Active'});save('Initialized demo chart of accounts')}
function ledgerDraft(){let opts=ledgerAccounts().filter(a=>a.status==='Active').map(a=>[a.code,a.code+' — '+a.name]);if(opts.length<2)return alert('Initialize the chart of accounts first.');form('Draft balanced journal entry',[['date','Transaction date','date'],['debit','Debit account','select',opts],['credit','Credit account','select',opts],['amount','Amount SSP','number'],['memo','Narration','text']],v=>{let n=Number(v.amount);if(v.debit===v.credit||!Number.isSafeInteger(n)||n<=0)return alert('Use distinct accounts and a positive whole SSP amount.');ledgerEntries().push({...v,id:financialId(),amount:n,status:'Draft'});save('Created balanced demo journal draft')})}
function ledgerPost(i){let e=ledgerEntries()[i];if(e.status!=='Draft')return;if(!e.date||!ledgerPeriods().some(p=>p.status==='Open'&&p.start<=e.date&&p.end>=e.date))return alert('Transaction date must fall in an open fiscal period.');if(e.debit===e.credit||!Number.isSafeInteger(Number(e.amount))||Number(e.amount)<=0||![e.debit,e.credit].every(c=>ledgerAccounts().some(a=>a.code===c&&a.status==='Active')))return alert('Invalid or inactive accounts.');if(confirm('Post balanced journal? Posted demo entries are locked.')){e.status='Posted';e.postedAt=new Date().toLocaleString();save('Posted demo journal entry')}}
function ledgerReverse(i){let e=ledgerEntries()[i];if(e.status!=='Posted'||e.reversedBy||e.reversalOf)return;form('Reverse posted demo entry',[['date','Reversal date','date'],['memo','Reason','text']],v=>{if(!ledgerPeriods().some(p=>p.status==='Open'&&p.start<=v.date&&p.end>=v.date))return alert('Select a date in an open period.');let id=financialId();ledgerEntries().push({id,date:v.date,memo:v.memo,debit:e.credit,credit:e.debit,amount:Number(e.amount),status:'Posted',reversalOf:e.id});e.reversedBy=id;save('Posted demo journal reversal')})}
function ledgerPeriod(){form('Open fiscal period',[['start','Start date','date'],['end','End date','date']],v=>{if(v.start>v.end||ledgerPeriods().some(p=>v.start<=p.end&&v.end>=p.start))return alert('Use non-overlapping dates.');ledgerPeriods().push({...v,status:'Open'});save('Opened demo fiscal period')})}
function ledgerClose(i){let p=ledgerPeriods()[i];if(p.status!=='Open')return;if(ledgerEntries().some(e=>e.status==='Draft'&&e.date>=p.start&&e.date<=p.end))return alert('Resolve journal drafts first.');if(confirm('Close this demo fiscal period?')){p.status='Closed';save('Closed demo fiscal period')}}
function ledgerTotals(){return ledgerAccounts().map(a=>{let entries=ledgerEntries().filter(e=>e.status==='Posted'),d=entries.filter(e=>e.debit===a.code).reduce((n,e)=>n+Number(e.amount),0),c=entries.filter(e=>e.credit===a.code).reduce((n,e)=>n+Number(e.amount),0);return {...a,d,c}})}
function ledgerView(){let tabs=['Chart of Accounts','Journal Entries','Account Ledger','Financial Reports','Fiscal Periods'];let body='';if(tab===0)body=btn('Initialize chart of accounts','ledgerSeed()')+table(['Code','Account','Type','Status'],ledgerAccounts().map(a=>[esc(a.code),esc(a.name),esc(a.type),esc(a.status)]));else if(tab===1)body=btn('New journal draft','ledgerDraft()')+' '+btn('Prepare linked journals','syncLedger()')+'<p>Eligible source transactions: '+sourceJournals().length+' · Review and post drafts manually. Older undated records use the current demo date; payroll with deductions is excluded.</p>'+table(['Date','Debit','Credit','Amount SSP','Narration','Status','Action'],ledgerEntries().map((e,i)=>[esc(e.date),esc(e.debit),esc(e.credit),money(e.amount),esc(e.memo),esc(e.status),e.status==='Draft'?btn('Post','ledgerPost('+i+')'):e.status==='Posted'&&!e.reversedBy&&!e.reversalOf?btn('Reverse','ledgerReverse('+i+')'):'—']));else if(tab===4)body=btn('Open fiscal period','ledgerPeriod()')+table(['Start','End','Status','Action'],ledgerPeriods().map((p,i)=>[esc(p.start),esc(p.end),esc(p.status),p.status==='Open'?btn('Close','ledgerClose('+i+')'):'—']));else{let totals=ledgerTotals();let d=totals.reduce((n,a)=>n+a.d,0),c=totals.reduce((n,a)=>n+a.c,0);body='<h2>Posted entries — '+(tab===3?'Trial balance':'Account totals')+'</h2>'+table(['Code','Account','Debit SSP','Credit SSP','Net debit SSP'],totals.map(a=>[esc(a.code),esc(a.name),money(a.d),money(a.c),money(a.d-a.c)]).concat([['','TOTAL',money(d),money(c),money(d-c)]]))+'<p>'+ (d===c?'Debit and credit totals agree.':'Warning: totals do not agree.')+'</p>'+(tab===3?financeReport():'')}return '<h1>General Ledger</h1><p>Manual fictional SSP journals · Not audited financial statements</p><div class="tabs">'+tabs.map((t,i)=>'<button class="'+(i===tab?'primary':'')+'" onclick="changeTab('+i+')">'+t+'</button>').join('')+'</div><div class="card">'+body+'</div>'}


const employees=()=>db.extra['/hr|0']??=[];
const leaves=()=>db.extra['/hr|1']??=[];
const payroll=()=>db.extra['/hr|2']??=[];
const attendance=()=>db.extra['/attendance|0']??=[];
const todayISO=()=>{let d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
employees().forEach(e=>{e.id??=financialId()});
function staffName(id){return employees().find(e=>e.id===id)?.name||id}
function employeeOptions(){return employees().filter(e=>e.status==='Active').map(e=>[e.id,e.name+' · '+e.department])}
function addEmployee(){form('Register fictional employee',[['name','Employee name','text'],['department','Department','text'],['role','Role','text'],['start','Start date','date'],['salary','Monthly base salary SSP','number']],v=>{if(!v.name.trim()||!Number.isSafeInteger(+v.salary)||+v.salary<0)return alert('Enter valid employee details.');employees().push({...v,id:financialId(),salary:+v.salary,status:'Active'});save('Registered fictional employee')})}
function employeeToggle(i){let e=employees()[i];if(e.status==='Active'&&attendance().some(a=>a.staff===e.id&&a.status==='On duty'))return alert('Clock out before deactivating staff.');if(confirm('Change employee status?')){e.status=e.status==='Active'?'Inactive':'Active';save('Updated employee status')}}
function leaveNew(){let opts=employeeOptions();if(!opts.length)return alert('Register active employees first.');form('Request fictional leave',[['staff','Employee','select',opts],['type','Leave type','select',[['Annual','Annual'],['Sick','Sick'],['Other','Other']]],['start','Start date','date'],['end','End date','date'],['reason','Reason','textarea']],v=>{if(v.start>v.end||leaves().some(l=>l.staff===v.staff&&['Pending','Approved'].includes(l.status)&&v.start<=l.end&&v.end>=l.start))return alert('Invalid or overlapping leave dates.');leaves().push({...v,id:financialId(),status:'Pending'});save('Requested fictional leave')})}
function leaveDecision(i){let l=leaves()[i];if(l.status!=='Pending')return;form('Review demo leave',[['status','Decision','select',[['Approved','Approved'],['Rejected','Rejected']]],['reviewer','Demo reviewer','text'],['comment','Comment','text']],v=>{Object.assign(l,v,{reviewedAt:new Date().toLocaleString()});save('Reviewed fictional leave')})}
function clockIn(){let day=todayISO(),opts=employeeOptions().filter(([id])=>!attendance().some(a=>a.staff===id&&a.status==='On duty')&&!leaves().some(l=>l.staff===id&&l.status==='Approved'&&l.start<=day&&day<=l.end));if(!opts.length)return alert('No eligible fictional staff available.');form('Clock in',[['staff','Employee','select',opts]],v=>{if(attendance().some(a=>a.staff===v.staff&&a.status==='On duty'))return;let now=new Date();attendance().push({id:financialId(),staff:v.staff,date:todayISO(),in:now.toLocaleTimeString(),inMs:now.getTime(),status:'On duty'});save('Demo staff clocked in')})}
function clockOut(i){let a=attendance()[i];if(a.status!=='On duty')return;let now=new Date();a.out=now.toLocaleTimeString();a.minutes=Math.max(0,Math.floor((now.getTime()-a.inMs)/60000));a.status='Recorded';save('Demo staff clocked out')}
function verifyAttendance(i){let a=attendance()[i];if(a.status==='Recorded'){a.status='Verified';save('Verified fictional attendance')}}
function attendanceTable(){return btn('Clock in','clockIn()')+table(['Employee','Date','Clock in','Clock out','Hours','Status','Action'],attendance().map((a,i)=>[esc(staffName(a.staff)),esc(a.date),esc(a.in),esc(a.out),Number.isFinite(a.minutes)?(a.minutes/60).toFixed(2):'—',esc(a.status),a.status==='On duty'?btn('Clock out','clockOut('+i+')'):a.status==='Recorded'?btn('Verify','verifyAttendance('+i+')'):'—']))}
function payrollNew(){let opts=employeeOptions();if(!opts.length)return alert('Register active employees first.');form('Draft monthly demo payroll',[['staff','Employee','select',opts],['month','Payroll month','month'],['allowances','Allowances SSP','number'],['deductions','Deductions SSP','number']],v=>{let e=employees().find(e=>e.id===v.staff),base=Number(e?.salary),a=+v.allowances,d=+v.deductions,gross=base+a,net=gross-d;if(![base,a,d,gross,net].every(x=>Number.isSafeInteger(x)&&x>=0)||payroll().some(p=>p.staff===v.staff&&p.month===v.month))return alert('Invalid amounts or duplicate payroll month.');payroll().push({...v,id:financialId(),base,allowances:a,deductions:d,amount:gross,net,status:'Draft'});save('Drafted fictional payroll')})}
function payrollStep(i){let p=payroll()[i];if(p.status==='Draft'){if(confirm('Approve this fictional payroll?')){p.status='Processed';p.processedAt=new Date().toLocaleString();save('Approved demo payroll')}}else if(p.status==='Processed'){form('Record simulated payroll payment',[['reference','Payment reference','text']],v=>{Object.assign(p,v,{status:'Paid',paidAt:new Date().toLocaleString(),paidDate:todayISO()});save('Recorded fictional payroll payment')})}}
function payrollPrint(i){let p=payroll()[i];if(!['Processed','Paid'].includes(p.status))return;let w=window.open('','_blank');if(!w)return alert('Allow pop-ups to print.');w.document.write('<html><head><title>Demo payslip</title></head><body style="font:14px Arial;margin:35px"><h1>MediTrack Pro — Payslip</h1><strong>FICTIONAL DEMO — NOT A PAYROLL RECORD</strong>'+[['Employee',staffName(p.staff)],['Month',p.month],['Base salary SSP',money(p.base)],['Allowances SSP',money(p.allowances)],['Gross SSP',money(p.amount)],['Deductions SSP',money(p.deductions)],['Net SSP',money(p.net)],['Status',p.status]].map(([l,v])=>'<p><b>'+l+':</b> '+esc(v)+'</p>').join('')+'</body></html>');w.document.close();w.print()}
function hrView(){let tabs=['Employees','Leave Requests','Payroll','Attendance'];let body=tab===0?btn('Register employee','addEmployee()')+table(['Name','Department','Role','Start','Base SSP','Status','Action'],employees().map((e,i)=>[esc(e.name),esc(e.department),esc(e.role),esc(e.start),money(e.salary),esc(e.status),btn(e.status==='Active'?'Deactivate':'Activate','employeeToggle('+i+')')])):tab===1?btn('Request leave','leaveNew()')+table(['Employee','Type','Start','End','Reason','Status','Action'],leaves().map((l,i)=>[esc(staffName(l.staff)),esc(l.type),esc(l.start),esc(l.end),esc(l.reason),esc(l.status),l.status==='Pending'?btn('Review','leaveDecision('+i+')'):'—'])):tab===2?btn('Draft payroll','payrollNew()')+table(['Employee','Month','Gross SSP','Deductions SSP','Net SSP','Status','Action'],payroll().map((p,i)=>[esc(staffName(p.staff)),esc(p.month),money(p.amount),money(p.deductions),money(p.net),esc(p.status),(p.status==='Draft'?btn('Approve','payrollStep('+i+')'):p.status==='Processed'?btn('Record payment','payrollStep('+i+')'):'')+(['Processed','Paid'].includes(p.status)?' '+btn('Print payslip','payrollPrint('+i+')'):'')])):attendanceTable();return '<h1>HR &amp; Payroll</h1><p>Fictional employee records and simulated payroll</p><div class="grid">'+[['Active employees',employeeOptions().length],['On duty',attendance().filter(a=>a.status==='On duty').length],['Pending leave',leaves().filter(l=>l.status==='Pending').length],['Paid payroll SSP',money(payroll().filter(p=>p.status==='Paid').reduce((n,p)=>n+Number(p.net||0),0))]].map(([l,v])=>'<div class="card">'+l+'<div class="stat">'+v+'</div></div>').join('')+'</div><div class="tabs">'+tabs.map((t,i)=>'<button class="'+(i===tab?'primary':'')+'" onclick="changeTab('+i+')">'+t+'</button>').join('')+'</div><div class="card">'+body+'</div>'}


function sourceJournals(){let rows=[];for(let b of db.bills){let revenue=({Lab:'4010',Imaging:'4030',Pharmacy:'4020',Services:'4080',Manual:'4080'})[b.department]||'4080';rows.push({source:'invoice:'+b.id,date:b.invoiceDate||todayISO(),debit:'1100',credit:revenue,amount:Number(b.amount),memo:'Demo invoice '+b.id})}for(let p of db.payments){let debit=({'Cash':'1000','Bank':'1010','Mobile money':'1020','Insurance':'1010'})[p.method];if(debit)rows.push({source:'receipt:'+p.id,date:p.paymentDate||todayISO(),debit,credit:'1100',amount:Number(p.amount),memo:'Demo receipt '+p.id})}for(let p of payroll().filter(p=>p.status==='Paid')){if(Number(p.deductions||0)!==0)continue;rows.push({source:'payroll:'+p.id,date:p.paidDate||todayISO(),debit:'5000',credit:'1000',amount:Number(p.net),memo:'Demo net payroll '+p.id})}return rows.filter(r=>Number.isSafeInteger(r.amount)&&r.amount>0&&!ledgerEntries().some(e=>e.source===r.source))}
function syncLedger(){let candidates=sourceJournals();let ready=candidates.filter(e=>[e.debit,e.credit].every(c=>ledgerAccounts().some(a=>a.code===c&&a.status==='Active'))&&ledgerPeriods().some(p=>p.status==='Open'&&p.start<=e.date&&e.date<=p.end));if(!ready.length)return alert('No eligible unposted transactions. Initialize accounts and open the fiscal period first.');if(!confirm('Create '+ready.length+' journal drafts for review?'))return;for(let e of ready){if(!ledgerEntries().some(x=>x.source===e.source))ledgerEntries().push({...e,id:financialId(),status:'Draft'})}save('Prepared balanced journal drafts from demo source transactions')}
function dateSource(x,k){x[k]??=todayISO()}
function prepareLedgerDates(){db.bills.forEach(b=>dateSource(b,'invoiceDate'));db.payments.forEach(p=>dateSource(p,'paymentDate'))}
prepareLedgerDates();
function financeReport(){let totals=ledgerTotals(),rev=totals.filter(a=>a.type==='Revenue').reduce((n,a)=>n+a.c-a.d,0),exp=totals.filter(a=>a.type==='Expense').reduce((n,a)=>n+a.d-a.c,0);return '<h2>Demo income statement — posted journals only</h2>'+table(['Measure','SSP'],[['Revenue',money(rev)],['Expenses',money(exp)],['Net result',money(rev-exp)]])+'<p>Excludes transactions not posted to the ledger, cost of goods sold and payroll deductions. Not an audited or complete financial statement.</p>'}


let reportMonth=todayISO().slice(0,7);
function reportMonthChange(v){if(/^\d{4}-(0[1-9]|1[0-2])$/.test(v)){reportMonth=v;render()}}
function reportInMonth(d){return typeof d==='string'&&d.slice(0,7)===reportMonth}
function reportSum(rows,fn){return rows.reduce((n,r)=>n+(Number(fn(r))||0),0)}
function reportData(){let invoices=db.bills.filter(b=>reportInMonth(b.invoiceDate)),payments=db.payments.filter(p=>reportInMonth(p.paymentDate)),journals=ledgerEntries().filter(e=>e.status==='Posted'&&reportInMonth(e.date)),staffPay=payroll().filter(p=>p.month===reportMonth),ins=claims().filter(c=>reportInMonth(c.reportDate)),visits=db.visits.filter(v=>reportInMonth(v.reportDate)),lab=db.lab.filter(v=>reportInMonth(v.reportDate)),rx=db.rx.filter(v=>reportInMonth(v.reportDate)),img=imagingRows().filter(v=>reportInMonth(v.reportDate)),ipd=admissions().filter(v=>reportInMonth(v.reportDate));let departments=[...new Set([...invoices.map(b=>b.department||'Manual'),...payments.map(p=>db.bills.find(b=>b.id===p.invoice)?.department||'Unallocated')])];let streams=departments.map(dept=>{let b=invoices.filter(b=>(b.department||'Manual')===dept),p=payments.filter(p=>(db.bills.find(b=>b.id===p.invoice)?.department||'Unallocated')===dept);return [dept,b.length,reportSum(b,x=>x.amount),reportSum(p,x=>x.amount),reportSum(b,balance)]});let accounts=ledgerAccounts().map(a=>({...a,d:reportSum(journals.filter(e=>e.debit===a.code),e=>e.amount),c:reportSum(journals.filter(e=>e.credit===a.code),e=>e.amount)}));let revenue=reportSum(accounts.filter(a=>a.type==='Revenue'),a=>a.c-a.d),expenses=reportSum(accounts.filter(a=>a.type==='Expense'),a=>a.d-a.c);return {invoices,payments,journals,staffPay,ins,visits,lab,rx,img,ipd,streams,accounts,revenue,expenses,billed:reportSum(invoices,b=>b.amount),collected:reportSum(payments,p=>p.amount),outstanding:reportSum(invoices,balance)}}
function reportStamp(){for(let x of [...db.visits,...db.lab,...db.rx,...imagingRows(),...admissions(),...claims()])x.reportDate??=todayISO()}
reportStamp();
function reportCards(items){return '<div class="grid">'+items.map(([l,v])=>'<div class="card"><small>'+esc(l)+'</small><div class="stat">'+esc(v)+'</div></div>').join('')+'</div>'}
function reportBars(rows){if(!rows.length)return '<p>No recorded activity for this month.</p>';let max=Math.max(1,...rows.map(r=>Math.max(0,Number(r[1])||0)));return '<div class="report-bars">'+rows.map(([l,v])=>'<div><div class="row"><span>'+esc(l)+'</span><strong>'+money(v)+'</strong></div><div class="report-track"><div style="width:'+Math.max(0,Math.min(100,100*Number(v)/max))+'%"></div></div></div>').join('')+'</div>'}
function reportSpec(){let d=reportData(),t=route==='/finance-analytics'?0:tab;let metrics=[['OPD visits',d.visits.length],['Lab orders',d.lab.length],['Prescriptions',d.rx.length],['Imaging requests',d.img.length],['Admissions',d.ipd.length]];if(t===1)return {title:'Income statement — posted journals',headers:['Measure','SSP'],rows:[['Revenue',d.revenue],['Expenses',d.expenses],['Net result',d.revenue-d.expenses]],note:'Posted journal activity only; excludes unposted transactions and incomplete cost accounting.'};if(t===2)return {title:'Insurance claims created this month',headers:['Status','Claims','Claimed SSP','Paid SSP'],rows:claimStates.map(st=>{let r=d.ins.filter(c=>c.status===st);return [st,r.length,reportSum(r,c=>c.amount),reportSum(r,c=>c.paid)]}),note:'Amounts and statuses are current values for claims created in the selected month, not historical snapshots.'};if(t===3)return {title:'Payroll by payroll month',headers:['Employee','Gross SSP','Deductions SSP','Net SSP','Status'],rows:d.staffPay.map(p=>[staffName(p.staff),p.amount,p.deductions||0,p.net||0,p.status]),note:'Includes drafts, approved and paid payroll; not a cash expenditure report.'};if(t===4)return {title:'Facility activity',headers:['Department / indicator','Count'],rows:[...metrics,['Completed OPD visits',d.visits.filter(v=>v.status==='Completed').length],['Released lab orders',d.lab.filter(v=>v.status==='Released').length],['Dispensed prescriptions',d.rx.filter(v=>v.status==='Completed').length],['Completed imaging',d.img.filter(v=>imagingStatus(v)==='Completed').length],['Discharged admissions',d.ipd.filter(v=>v.status==='Discharged').length]],note:'Current status of encounters or orders created in this month, not completion events during the month.'};if(t===5)return {title:'Expense insights — posted ledger',headers:['Expense account','Net expense SSP'],rows:d.accounts.filter(a=>a.type==='Expense').map(a=>[a.name,a.d-a.c]),note:'Only posted expense accounts; payroll and inventory costs may be incomplete.'};if(t===6)return {title:'Financial health',headers:['Indicator','Value'],rows:[['Invoices created SSP',d.billed],['Receipts recorded SSP',d.collected],['Current balance on month invoices SSP',d.outstanding],['Posted net result SSP',d.revenue-d.expenses],['Posted expense / revenue ratio',d.revenue>0?(100*d.expenses/d.revenue).toFixed(1)+'%':'Not available']],note:'Receipt totals are by payment date, invoice balances are current, and posted results are by journal date. These are different bases.'};return {title:'Departmental revenue streams',headers:['Department','Invoices','Billed SSP','Receipts SSP','Current balance SSP'],rows:d.streams,note:'Receipts include recorded insurer payments and payments on earlier invoices. Outstanding balances relate to invoices created during the selected month.'}}
function reportCSV(){let r=reportSpec(),q=v=>{let str=String(v??'');if(/^[\s]*[=+@-]/.test(str))str="'"+str;return '"'+str.replace(/"/g,'""')+'"'};let lines=[[r.title,reportMonth],r.headers,...r.rows,[r.note]].map(row=>row.map(q).join(',')).join('\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([lines],{type:'text/csv;charset=utf-8'}));a.download='meditrack-demo-'+reportMonth+'.csv';a.click();URL.revokeObjectURL(a.href)}
let dashboardPeriod='all',sidebarCollapsed=false;
function dashboardPeriodChange(v){dashboardPeriod=v;render()}
function dashboardView(){let date=todayISO(),month=date.slice(0,7),match=d=>dashboardPeriod==='all'||(typeof d==='string'&&(dashboardPeriod==='today'?d===date:d.slice(0,7)===month)),vs=db.visits.filter(v=>match(v.reportDate)),ls=db.lab.filter(v=>match(v.reportDate)),rs=db.rx.filter(v=>match(v.reportDate)),ps=db.payments.filter(p=>match(p.paymentDate)),insured=new Set(policies().filter(p=>p.status==='Active').map(p=>p.patient)),staff=employees().filter(e=>e.status==='Active'&&/doctor|physician|medical officer|medical director/i.test(e.role||'')),pending=ls.filter(x=>!['Released','Completed','Cancelled'].includes(x.status)),receipts=reportSum(ps,p=>p.amount);let metrics=[['OPD visits',vs.length,'/opd'],['Current IPD admissions',activeAdmissions().length,'/ipd'],['Available beds',availableBeds().length,'/ipd'],['Lab orders',ls.length,'/lab'],['Rx pending',rs.filter(x=>x.status==='Pending').length,'/pharmacy'],['Rx dispensed',rs.filter(x=>x.status==='Completed').length,'/pharmacy'],['Active registered doctors',staff.length,'/hr'],['Staff on duty',attendance().filter(a=>a.status==='On duty').length,'/attendance'],['Patients without active cover',db.patients.filter(p=>!insured.has(p.id)).length,'/patients'],['Patients with active cover',db.patients.filter(p=>insured.has(p.id)).length,'/insurance'],['Total registered patients',db.patients.length,'/patients'],['Receipts (SSP)',money(receipts),'/billing']];let depts=[...new Set(ps.map(p=>db.bills.find(b=>b.id===p.invoice)?.department||'Unallocated'))];return '<div class="row"><div><h1>Welcome, Demo Administrator</h1><p>Hospital operations overview</p></div><label>Activity period<select onchange="dashboardPeriodChange(this.value)">'+[['all','All demo activity'],['today','Today'],['month','This month']].map(([v,l])=>'<option value="'+v+'" '+(v===dashboardPeriod?'selected':'')+'>'+l+'</option>').join('')+'</select></label></div><div class="grid dashboard-metrics">'+metrics.map(x=>card(...x)).join('')+'</div><p>Bed, staff and patient registry metrics show current totals regardless of period. Activity status reflects the current state of selected records.</p><div class="grid dashboard-panels"><div class="card"><h2>Revenue breakdown</h2>'+reportBars(depts.map(d=>[d,reportSum(ps.filter(p=>(db.bills.find(b=>b.id===p.invoice)?.department||'Unallocated')===d),p=>p.amount)]))+'</div><div class="card"><h2>Clinical summary</h2>'+table(['Indicator','Count'],[['Waiting',vs.filter(v=>v.status==='Waiting').length],['In consultation',vs.filter(v=>v.status==='In consultation').length],['Completed',vs.filter(v=>v.status==='Completed').length]])+'</div><div class="card"><h2>Laboratory summary</h2>'+table(['Indicator','Count'],[['Awaiting release',pending.length],['Released',ls.filter(x=>x.status==='Released').length]])+'</div><div class="card"><h2>Pharmacy summary</h2>'+table(['Indicator','Count'],[['Pending prescriptions',rs.filter(x=>x.status==='Pending').length],['Low stock batches',db.drugs.filter(d=>d.qty<=5).length]])+'</div></div><div class="card"><h2>Operational alerts</h2>'+table(['Indicator','Count','Workspace'],[['Unreleased tests',pending.length,btn('Laboratory',"nav('/lab')")],['Outstanding invoices',db.bills.filter(b=>balance(b)>0).length,btn('Accounts',"nav('/billing')")],['Pending leave requests',leaves().filter(l=>l.status==='Pending').length,btn('HR',"nav('/hr')")]])+'</div>'}
function toggleSidebar(){if(window.innerWidth<=720){document.querySelector('#sidebar').classList.toggle('open');return}sidebarCollapsed=!sidebarCollapsed;render()}
const navGlyphs=['▦','◉','▤','⚙','⌕','＋','☷','▣','▥','✚','♡','⚗','▧','◈','↗','▦','$','▤','▥','◇','◷','♙','▥','⚙','▤','▣'];
function navGlyph(r){let i=groups.flatMap(g=>g[1]).findIndex(x=>x[1]===r);return navGlyphs[i]||'•'}
function reportPrint(){let r=reportSpec(),w=window.open('','_blank');if(!w)return alert('Allow pop-ups to print.');w.document.write('<!doctype html><html><head><title>Demo report</title><style>body{font:14px Arial;margin:32px}table{width:100%;border-collapse:collapse}td,th{border:1px solid #ccc;padding:8px;text-align:left}</style></head><body><h1>MediTrack Pro</h1><strong>FICTIONAL DEMO — NOT AN AUDITED REPORT</strong><h2>'+esc(r.title)+' · '+esc(reportMonth)+'</h2>'+table(r.headers,r.rows.map(row=>row.map(esc)))+'<p>'+esc(r.note)+'</p></body></html>');w.document.close();w.print()}
function reportsView(){let d=reportData(),r=reportSpec(),tabs=['Revenue insights','Income statement','Insurance','Payroll','Facility performance','Expense insights','Financial health'];return '<div class="row"><div><h1>'+ (route==='/finance-analytics'?'Finance analytics':'Reports')+'</h1><p>Monthly reporting · fictional SSP records</p></div><label>Reporting month<input type="month" value="'+esc(reportMonth)+'" onchange="reportMonthChange(this.value)"></label></div>'+reportCards([['Invoiced SSP',money(d.billed)],['Receipts SSP',money(d.collected)],['Current balance SSP',money(d.outstanding)],['Posted net result SSP',money(d.revenue-d.expenses)]])+(route==='/reports'?'<div class="tabs">'+tabs.map((t,i)=>'<button class="'+(i===tab?'primary':'')+'" onclick="changeTab('+i+')">'+t+'</button>').join('')+'</div>':'')+'<div class="card"><div class="row"><h2>'+esc(r.title)+'</h2>'+btn('Export CSV','reportCSV()')+btn('Print report','reportPrint()')+'</div><p>'+esc(r.note)+'</p>'+((route==='/finance-analytics'||tab===0)?reportBars(d.streams.map(x=>[x[0],x[3]])):'')+table(r.headers,r.rows.map(row=>row.map(v=>typeof v==='number'?money(v):esc(v))))+'<p>Legacy undated clinical and claim records are assigned the demo migration date. No refunds, cost of goods sold or original facility data are imported.</p></div>'}
render();
